const fs=require('node:fs'),assert=require('node:assert/strict'),{JSDOM}=require('jsdom');
const prefix='school/family-android/app/src/main/assets/';
function fixture(role='parent'){
 const dom=new JSDOM('<!doctype html><html><head></head><body><div id="toasts"></div><div id="root"></div></body></html>',{url:'https://maakit.in/school/',runScripts:'dangerously',pretendToBeVisual:true});
 const w=dom.window;w.fetch=()=>new Promise(()=>{});w.scrollTo=()=>{};w.matchMedia=()=>({matches:false});
 w.HTMLDialogElement.prototype.showModal=function(){this.setAttribute('open','')};w.HTMLDialogElement.prototype.close=function(){this.removeAttribute('open')};
 const app=w.document.createElement('script');app.textContent=fs.readFileSync('school/app.js','utf8');w.document.head.appendChild(app);
 w.eval("STATUS={school:'QA School',teachers:[]};U={role:"+JSON.stringify(role)+"};S=emptyState();S.settings={school:'QA School',session:'2026-27'};PD={kids:[{id:'qa1',name:'QA Child One',cls:'5th'},{id:'qa2',name:'QA Child Two',cls:'3rd'}],att:[{sid:'qa1',date:todayISO(),present:true},{sid:'qa2',date:todayISO(),present:false}],hw:[{cls:'5th',date:todayISO(),subj:'Maths',hw:'QA homework ONE',topic:'Fractions'},{cls:'3rd',date:todayISO(),subj:'English',hw:'QA homework TWO',topic:'Nouns'}],marks:[{sid:'qa1',exam:'e1',subj:'Maths',mark:42,max:50}],behav:[],speak:[],remarks:[],notices:[],fees:null};S.exams=[{id:'e1',name:'QA Exam',date:todayISO()}];PKID='qa1';view='phome';");
 w.eval(fs.readFileSync(prefix+'language.js','utf8'));w.eval(fs.readFileSync(prefix+'family-style.js','utf8'));w.eval(fs.readFileSync(prefix+'family-ui.js','utf8'));w.SNFamily.closeIntro();
 return {dom,w};
}
let {dom,w}=fixture();
assert.equal(w.document.querySelectorAll('.fam-tab').length,5);
assert(w.document.querySelector('.fam-child').textContent.includes('QA Child One'));
assert(w.document.querySelector('.fam-stats').textContent.includes('100%'));
assert(!w.document.querySelector('.fam-real-screen').textContent.includes('QA homework TWO'));
w.eval("view='phw';render()");
assert(w.document.querySelector('.fam-phone').style.getPropertyValue('--fa')==='#ed641c');
assert(w.document.querySelector('.fam-real-screen').textContent.includes('QA homework ONE'));
assert(!w.document.querySelector('.fam-real-screen').textContent.includes('QA homework TWO'));
w.eval("PKID='qa2';render()");
assert(w.document.querySelector('.fam-real-screen').textContent.includes('QA homework TWO'));
assert(!w.document.querySelector('.fam-real-screen').textContent.includes('QA homework ONE'));
w.eval("PKID='qa1';view='presults';render()");
assert(w.document.querySelector('.fam-real-screen').textContent.includes('42 / 50'));
assert.equal(w.document.querySelector('.fam-phone').style.getPropertyValue('--fa'),'#14915a');
w.eval("view='pfees';render()");
assert(!w.document.querySelector('.fam-real-screen').textContent.includes('could not open'));
w.eval("view='pnotices';render()");
assert(w.document.querySelector('.fam-real-screen').textContent.includes('Change PIN'));
w.SNFamily.menu();assert(w.document.querySelector('#fam-menu').open);
assert(w.document.querySelector('#fam-menu').textContent.includes('Game Zone'));
w.SNFamily.intro();assert.equal(w.document.querySelectorAll('#fam-intro').length,1);w.SNFamily.closeIntro();
w.eval("U=null;S=null;MUST={role:'parent',old:'1234'};render()");
assert(w.document.querySelector('#mc-pin'),'mandatory PIN change preserved');
assert(!w.document.querySelector('#lg-ph'),'does not bypass mandatory PIN screen');
assert.equal(w.document.querySelectorAll('#fam-intro').length,0);
dom.window.close();
({dom,w}=fixture('student'));
assert(!w.document.querySelector('.fam-tabs').textContent.includes('Fees'));
assert(w.document.querySelector('.fam-tabs').textContent.includes('Play'));
assert(!w.document.querySelector('#fam-menu').textContent.includes('Staff'));
dom.window.close();
console.log('Family design: real ERP render, child switch/scoped homework, attendance, results, fees, student restrictions, intro, account sheet and mandatory PIN passed');
